// ===========================
// 制度の計算機 — インボイス 2割特例の後（3割特例・簡易課税・本則課税）の値の表（値・出典・確認日をセットで）
// 対象: 免税事業者からインボイス発行事業者になった個人事業者の、令和9年分〜令和11年分（2027〜2029年）の消費税。
// どの値も下の SOURCES の原文（e-Gov 法令検索・国税庁・財務省）を 2026-09-25 に読んで写した。
// ブラウザでは window.InvoiceValues、Node（テスト）では module.exports で使う
// ===========================
(function (root) {
  'use strict';

  var CHECKED = '2026-09-25';   // 下の出典を最後に原文で確かめた日
  var NTA = 'https://www.nta.go.jp/';
  var KZ = NTA + 'taxes/shiraberu/zeimokubetsu/shohi/keigenzeiritsu/';

  var SOURCES = [
    { key: 'review', label: '国税庁 インボイス制度特設サイト「令和８年度税制改正特集」', url: KZ + 'invoice-review/index.htm', where: '3割特例（個人事業者・令和9年分と令和10年分・基準期間の課税売上高1,000万円以下・登録を受けていること）、簡易課税への円滑な移行措置、事業区分とみなし仕入率、7・5・3割控除（令和8年10月から70%、令和10年10月から50%、令和12年10月から30%、令和13年10月から0%）' },
    { key: 'leaflet', label: '国税庁 リーフレット「インボイス制度に関する令和８年度税制改正について」（令和8年4月、5月改訂）', url: KZ + 'invoice-review/pdf/0026004-099-01-1.pdf', where: '3割特例は課税標準額に対する消費税額から、その7割を控除する。2割特例は令和8年9月30日までの日の属する課税期間で終了。2割・3割特例の翌課税期間は、その申告期限までに簡易課税の届出を出せばその期間から簡易課税（令和11年分は令和12年4月1日まで）' },
    { key: 'qa1153', label: '国税庁 インボイスQ&A 問115-2（3割特例の適用ができない課税期間）【令和8年4月追加】', url: KZ + 'pdf/qa/115-2.pdf', where: '28年改正法附則51条の3第1項。基準期間の課税売上高1,000万円超、課税期間の短縮、調整対象固定資産・高額特定資産の仕入れ等で免税点が制限される課税期間などは不可' },
    { key: 'qa1173', label: '国税庁 インボイスQ&A 問117-3（3割特例より簡易課税が有利な場合）【令和8年4月追加】', url: KZ + 'pdf/qa/117-3.pdf', where: '小売業（第2種 80%）は簡易課税のほうが少ない。届出は翌課税期間の確定申告期限まで（土日・祝日などは翌日）。簡易課税は基準期間の課税売上高5,000万円以下、2年間は継続' },
    { key: 'qa130', label: '国税庁 インボイスQ&A 問130（免税事業者等からの課税仕入れに係る経過措置の税額計算）【令和8年4月改訂】', url: KZ + 'pdf/qa/130.pdf', where: '割戻し計算: 支払対価の額の合計 × 7.8/110 × 割合（令和5年10月〜令和8年9月 80%、令和8年10月〜令和10年9月 70%、令和10年10月〜令和12年9月 50%、令和12年10月〜令和13年9月 30%）。令和8年10月1日以後に開始する課税期間は、一の免税事業者等からの分が税込1億円まで' },
    { key: 'ta6505', label: '国税庁 タックスアンサー No.6505 簡易課税制度［令和8年4月1日現在法令等］', url: NTA + 'taxes/shiraberu/taxanswer/shohi/6505.htm', where: 'みなし仕入率 第1種90%・第2種80%・第3種70%・第4種60%・第5種50%・第6種40%。原則は課税期間の初日の前日までに届出。根拠 消法37条・平28改正法附則51条の2・51条の3' },
    { key: 'niwari', label: '国税庁「２割特例（インボイス発行事業者となる小規模事業者に対する負担軽減措置）の概要」', url: NTA + 'publication/pamph/shohi/kaisei/202304/01.htm', where: '特別控除税額 ＝（課税標準額に対する消費税額 − 売上げの返還等に係る消費税額）× 80%。令和5年10月1日から令和8年9月30日までの日の属する課税期間（個人は令和8年分まで）' },
    { key: 'tebiki', label: '国税庁「２割特例用 消費税及び地方消費税の確定申告の手引き」（設例 国税太郎）', url: NTA + 'publication/pamph/pdf/0023008-043.pdf', where: '税込 × 100/110（1円未満切り捨て）→ 課税標準額（1,000円未満切り捨て）× 7.8%。返還等 × 7.8/110。特別控除税額 ×80%（切り捨て）。差引税額は100円未満切り捨て。設例 6,609,330円 → 課税標準額 6,008,000円・消費税額 468,624円・差引税額 90,900円（テストで再現）' },
    { key: 'shohi', label: '消費税法 29条（税率 7.8%・軽減 6.24%）・30条・37条（簡易課税）', url: 'https://laws.e-gov.go.jp/law/363AC0000000108', where: '令和8年4月1日施行版（令和8年法律第12号による改正後）' },
    { key: 'tsusoku', label: '国税通則法 118条・119条', url: 'https://laws.e-gov.go.jp/law/337AC0000000066', where: '課税標準の1,000円未満、確定金額の100円未満を切り捨て' },
    { key: 'chiho', label: '地方税法 72条の82・72条の83・20条の4の2', url: 'https://laws.e-gov.go.jp/law/325AC0000000226', where: '地方消費税は消費税額を課税標準とし、税率は78分の22。確定金額の100円未満を切り捨て' },
    { key: 'mof', label: '財務省「特集 令和8年度税制改正（国税）等について」（ファイナンス 令和8年4月号）', url: 'https://www.mof.go.jp/public_relations/finance/202604/202604c.html', where: '所得税法等の一部を改正する法律案は令和8年3月31日に成立。3割特例は2年に限る経過措置。8割控除は7割・5割・3割と縮減し令和13年9月末で終了' },
    { key: 'hikisage', label: '国税庁 消費税率引下げ特設サイト（令和8年9月15日開設）・リーフレット', url: KZ + 'zeiritsuhikisage.htm', where: '飲食料品の税率を令和9年4月1日から令和11年3月31日まで1%にする案（令和8年9月15日閣議決定の大綱）。法案の成立が前提で、2026-09-25 時点では法律になっていない。このツールは飲食料品（軽減税率）を扱わない' },
  ];

  var V = {
    CHECKED: CHECKED,
    STALE_MONTHS: 12,             // 確認日からこの月数がたったら画面に注意を出す
    SOURCES: SOURCES,

    // 計算する年分（個人事業者の課税期間は 1〜12 月）
    years: {
      2027: { label: '令和9年分', sanwari: true,  kigen: '2028-03-31' },
      2028: { label: '令和10年分', sanwari: true,  kigen: '2029-04-02' },   // 3/31 が土曜 → 4/1 は日曜 → 4/2（月）
      2029: { label: '令和11年分', sanwari: false, kigen: '2030-04-01' },   // 3/31 が日曜 → 4/1（国税庁のリーフレットと同じ）
    },
    defaultYear: 2027,

    // 税率（標準税率 10% のうち国 7.8%）。地方消費税は消費税額の 22/78
    kokuRate: [78, 1000],         // 7.8%
    chihoRate: [22, 78],
    // 2割特例・3割特例: 控除する割合（売上税額の 80% / 70%）
    niwariKojo: 80,
    sanwariKojo: 70,
    // 簡易課税の事業区分とみなし仕入率（消法37条・消令57条、タックスアンサー No.6505）
    kubun: [
      { n: 1, rate: 90, name: '第1種（卸売業）' },
      { n: 2, rate: 80, name: '第2種（小売業など）' },
      { n: 3, rate: 70, name: '第3種（製造業・建設業など）' },
      { n: 4, rate: 60, name: '第4種（飲食店業など、ほかに当たらないもの）' },
      { n: 5, rate: 50, name: '第5種（サービス業・運輸通信業・金融保険業）' },
      { n: 6, rate: 40, name: '第6種（不動産業）' },
    ],
    defaultKubun: 5,
    // インボイスのない課税仕入れ（免税事業者・消費者から）の経過措置: 課税仕入れを行った日で割合が決まる
    keika: [
      { from: '2023-10-01', to: '2026-09-30', pct: 80 },
      { from: '2026-10-01', to: '2028-09-30', pct: 70 },
      { from: '2028-10-01', to: '2030-09-30', pct: 50 },
      { from: '2030-10-01', to: '2031-09-30', pct: 30 },
    ],
    // 3割特例・2割特例は基準期間（2年前）の課税売上高 1,000万円以下、簡易課税は 5,000万円以下
    menzeiLimit: 10000000,
    kaniLimit: 50000000,
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = V;
  else root.InvoiceValues = V;
})(this);
